document.addEventListener('DOMContentLoaded', () => {

  // ==============================
  // ① スクロール + ウィンドウサイズ制御
  // ==============================
  function scrollAnimationSet() {
    const scButtonWrap = document.getElementById('scrollTopWrap');
    const position = document.documentElement;
    let wHeight = window.innerHeight;
    let ticking = false;

    // 高さ・スクロール値更新
    function updateProperties() {
      wHeight = window.innerHeight;
      position.style.setProperty('--wHeight', wHeight);
      position.style.setProperty('--wHeightPx', `${wHeight}px`);
      position.style.setProperty('--scroll', window.scrollY);

      // ボタン表示切り替え
      if (window.scrollY > wHeight) {
        scButtonWrap?.classList.add('display');
      } else {
        scButtonWrap?.classList.remove('display');
      }
    }

    // スクロールハンドラ（requestAnimationFrameで間引き）
    function onScroll() {
      if (!ticking) {
        requestAnimationFrame(() => {
          updateProperties();
          ticking = false;
        });
        ticking = true;
      }
    }

    // リサイズ対応
    function onResize() {
      wHeight = window.innerHeight;
      position.style.setProperty('--wHeightFixedPx', `${wHeight}px`);
      updateProperties();
    }

    // 初期化
    function init() {
      updateProperties();
      position.style.setProperty('--wHeightFixedPx', `${wHeight}px`);
      window.addEventListener('scroll', onScroll, { passive: true });
      window.addEventListener('resize', onResize);
    }

    init();
  }

  scrollAnimationSet();

  // ==============================
  // ② ローディングアニメーション（軽量化）
  // ==============================
  function loadingAnimation() {
    const duration = 1000;
    const duration2 = 2500;
    const loadingLogo = document.getElementById('loadingLogo');
    const loading = document.getElementById('loading');
    const article = document.querySelector('article');
    const body = document.body;

    if (!loadingLogo || !loading) return;

    loadingLogo.classList.add('load');
    window.deleteState = 1;

    setTimeout(() => {
      loadingLogo.classList.remove('load');
      setTimeout(() => {
        loading.classList.add('loaded');
        article?.classList.remove('loading');
        setTimeout(() => body.classList.remove('bind'), duration);
      }, duration);
    }, duration2);
  }

  if (document.getElementById('index')) {
    loadingAnimation();
  }

  // ==============================
  // ③ ハンバーガーメニュー開閉（軽量化）
  // ==============================
  function humMenuToggle() {
    const humButton = document.querySelector('#humMenu button');
    const closeBtn = document.getElementById('humClose');
    const menuBg = document.getElementById('menuBg');
    const header = document.querySelector('header');
    const headerLogoLink = document.getElementById('headerLogoLink');
    const slideMenu = document.getElementById('slideMenuNew');
    let menuState = 0;

    if (!humButton || !slideMenu) return;

    const toggleMenu = () => {
      if (menuState === 0) {
        slideMenu.classList.add('open');
        header?.classList.add('hum_open');
        headerLogoLink?.setAttribute('linktype', 'headerLink');
        menuState = 1;
      } else {
        slideMenu.classList.remove('open');
        header?.classList.remove('hum_open');
        headerLogoLink?.setAttribute('linktype', 'normalLink');
        menuState = 0;
      }
    };

    humButton.addEventListener('click', toggleMenu);
    closeBtn?.addEventListener('click', toggleMenu);
    menuBg?.addEventListener('click', toggleMenu);
  }

  humMenuToggle();

  // ==============================
  // ④ ページ読込後の初期化処理（軽量版）
  // ==============================
  function preSetScript() {
    // スクロールトップ矢印
    const arrow = document.querySelector('.header_arrow a');
    if (arrow) {
      arrow.addEventListener('click', e => {
        e.preventDefault();
        window.scrollTo({ top: 0, behavior: 'smooth' });
      });
    }

    // 数量カウンター
    const minus = document.getElementById('minusButton');
    const plus = document.getElementById('plusButton');
    const quantityInput = document.getElementById('quantityInput');
    if (minus && plus && quantityInput) {
      minus.addEventListener('click', e => {
        e.preventDefault();
        const value = Math.max(1, parseInt(quantityInput.value) - 1);
        quantityInput.value = value;
      });
      plus.addEventListener('click', e => {
        e.preventDefault();
        const value = parseInt(quantityInput.value) + 1;
        quantityInput.value = value;
      });
    }
  }

  preSetScript();

});
